import AppHeader from '../Components/AppHeader.vue'
import type { Statistics } from '../types'
defineProps<{ statistics: Statistics; difficultQuestions: Array<{ question_id:number; attempts:number; errors:number; question:{ text:string; ticket_number:number; position:number } }> }>()
const resetStatistics = () => {
  if (window.confirm('Сбросить всю статистику и историю прохождений? Это действие нельзя отменить.')) router.delete('/statistics')
}
</script>
